changeSet.sql:
CREATE TABLE IF NOT EXISTS user_role (
authorized_user_id BIGINT NOT NULL,
role_list_id BIGINT NOT NULL,
CONSTRAINT fk_authorized_user
FOREIGN KEY (authorized_user_id)
REFERENCES authorized_user (authorized_user_id)
ON DELETE CASCADE,
CONSTRAINT fk_role_list
FOREIGN KEY (role_list_id)
REFERENCES role_list (role_list_id)
ON DELETE CASCADE,
PRIMARY KEY (authorized_user_id, role_list_id)
);
CREATE INDEX idx_user_role_user_id ON user_role(authorized_user_id);
CREATE INDEX idx_user_role_role_id ON user_role(role_list_id);
CREATE UNIQUE INDEX idx_authorized_user_login_id ON authorized_user(login_id);

CREATE TABLE IF NOT EXISTS user_group ( group_id BIGINT AUTO_INCREMENT PRIMARY KEY, group_name VARCHAR(255) UNIQUE NOT NULL, description TEXT, tenant_id BIGINT NOT NULL, is_active TINYINT(1) DEFAULT 1, created_by VARCHAR(255), created_at TIMESTAMP, modified_by VARCHAR(255), modified_at TIMESTAMP, CONSTRAINT fk_user_group_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(tenant_id) );
CREATE TABLE IF NOT EXISTS group_role ( group_id BIGINT NOT NULL, role_list_id BIGINT NOT NULL, CONSTRAINT fk_group_role_group FOREIGN KEY (group_id) REFERENCES user_group(group_id) ON DELETE CASCADE, CONSTRAINT fk_group_role_role FOREIGN KEY (role_list_id) REFERENCES role_list(role_list_id) ON DELETE CASCADE, PRIMARY KEY (group_id, role_list_id) );
CREATE TABLE IF NOT EXISTS user_group_mapping ( authorized_user_id BIGINT NOT NULL, group_id BIGINT NOT NULL, CONSTRAINT fk_user_group_mapping_user FOREIGN KEY (authorized_user_id) REFERENCES authorized_user(authorized_user_id) ON DELETE CASCADE, CONSTRAINT fk_user_group_mapping_group FOREIGN KEY (group_id) REFERENCES user_group(group_id) ON DELETE CASCADE, PRIMARY KEY (authorized_user_id, group_id) );

-- Add tenant_id column to authorized_user table
ALTER TABLE authorized_user ADD COLUMN tenant_id BIGINT;
ALTER TABLE authorized_user ADD CONSTRAINT fk_authorized_user_tenant 
    FOREIGN KEY (tenant_id) REFERENCES tenant(tenant_id);

-- Add tenant_id column to role_list table
ALTER TABLE role_list ADD COLUMN tenant_id BIGINT;
ALTER TABLE role_list ADD CONSTRAINT fk_role_list_tenant 
    FOREIGN KEY (tenant_id) REFERENCES tenant(tenant_id);

-- Add tenant_id column to authority_list table
ALTER TABLE authority_list ADD COLUMN tenant_id BIGINT;
ALTER TABLE authority_list ADD CONSTRAINT fk_authority_list_tenant 
    FOREIGN KEY (tenant_id) REFERENCES tenant(tenant_id);

-- Add tenant_id column to password_reset_token table
ALTER TABLE password_reset_token ADD COLUMN tenant_id BIGINT;
ALTER TABLE password_reset_token ADD CONSTRAINT fk_password_reset_token_tenant 
    FOREIGN KEY (tenant_id) REFERENCES tenant(tenant_id);

